import{_ as e,o as a,c as r,a5 as n}from"./chunks/framework.CXroN2RO.js";const o="/study/images/game/prefabs-and-object-lifetimes.svg",b=JSON.parse('{"title":"プレハブと生成・破棄の基本 — 同じ部品から複数の物を作る","description":"","frontmatter":{"title":"プレハブと生成・破棄の基本 — 同じ部品から複数の物を作る","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"Unityのプレハブから敵や弾を作る場面で、ひな形とインスタンス、個別の状態と共有アセット、生成・有効化・無効化・破棄の違いを説明する。","aliases":["プレハブ","Prefab","インスタンス","instance","Instantiate","生成","破棄","Destroy","ライフサイクル","Awake","Start","OnEnable","OnDisable","オブジェクトプール"],"verification":"Unity 6.0のプレハブ・Instantiate・イベント関数・SetActive・Destroyの公式資料に照合（2026-11-07）"}},"headers":[],"relativePath":"game/basics/prefabs-and-object-lifetimes.md","filePath":"game/basics/prefabs-and-object-lifetimes.md"}'),s={name:"game/basics/prefabs-and-object-lifetimes.md"};function i(c,t,d,l,h,m){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="プレハブと生成・破棄の基本-—-同じ部品から複数の物を作る" tabindex="-1">プレハブと生成・破棄の基本 — 同じ部品から複数の物を作る <a class="header-anchor" href="#プレハブと生成・破棄の基本-—-同じ部品から複数の物を作る" aria-label="Permalink to &quot;プレハブと生成・破棄の基本 — 同じ部品から複数の物を作る&quot;">​</a></h1><p>同じ見た目と動きを持つ敵を何体も置きたいとします。形、当たり判定、操作するスクリプトなどを、毎回一つずつ設定する代わりに、ひな形から作れます。Unityでは、GameObjectとその部品・設定を再利用するためのアセットを<strong>プレハブ</strong>と呼びます。ここではUnity 6.0のGameObjectを例にします。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/Prefabs.html" target="_blank" rel="noreferrer">Unityのプレハブ</a> · <a href="/study/game/basics/scenes-and-components.html">シーンとコンポーネント</a></p><h2 id="ひな形と、実際に動く一体" tabindex="-1">ひな形と、実際に動く一体 <a class="header-anchor" href="#ひな形と、実際に動く一体" aria-label="Permalink to &quot;ひな形と、実際に動く一体&quot;">​</a></h2><p>プレハブアセットをもとに作った実体を<strong>インスタンス</strong>と呼びます。プレハブに敵の部品と初期HPを用意し、シーンに複数のインスタンスを置けます。プレハブから継承する設定と、個々のインスタンスで上書きする設定もあります。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/PrefabInstanceOverrides.html" target="_blank" rel="noreferrer">Unityのプレハブインスタンス</a></p><table tabindex="0"><thead><tr><th>データ</th><th>敵を二体作る例</th></tr></thead><tbody><tr><td><strong>プレハブアセット</strong></td><td>部品、初期HP、使う素材などのひな形。</td></tr><tr><td><strong>インスタンスの状態</strong></td><td>敵Aと敵Bが持つ位置、現在HP、攻撃中かどうか。</td></tr><tr><td><strong>参照するアセット</strong></td><td>描画用のメッシュやマテリアルなど。複数の敵から同じ素材を参照できる。</td></tr></tbody></table><p>例えばAがダメージを受けたら、Aの現在HPを70へ更新し、Bの現在HPは100を保つ設計にします。一方、共有するアセットの設定を変えた場合は、同じアセットを使う他の物にも影響し得ます。個々の状態と、参照先のデータをそれぞれ確認します。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/Prefabs.html" target="_blank" rel="noreferrer">Unityのプレハブの考え方</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Renderer-sharedMaterial.html" target="_blank" rel="noreferrer">共有マテリアル</a></p><figure class="study-figure"><img src="'+o+'" alt="敵のプレハブから敵Aと敵Bを作り、それぞれが位置とHPを持つ。AのHPは70、Bは100。描画用のメッシュやマテリアルは共有する参照先にできる。有効・無効の切り替えと、インスタンスを破棄する操作を区別する。" width="760" height="470" loading="lazy"><figcaption>ひな形、個別に変わる値、複数の物から参照する素材の関係を示します。<a href="/study/images/game/prefabs-and-object-lifetimes.svg" target="_blank" rel="noopener noreferrer">プレハブと状態の図を拡大</a></figcaption></figure><h2 id="実行中に生成する" tabindex="-1">実行中に生成する <a class="header-anchor" href="#実行中に生成する" aria-label="Permalink to &quot;実行中に生成する&quot;">​</a></h2><p>Unityの<code>Instantiate</code>は、指定したオブジェクトを複製し、その参照を返します。プレハブをもとに弾や敵を作り、位置や初期状態を設定する場面で使えます。子のGameObjectやコンポーネントも複製され、生成元の有効状態も引き継がれます。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Object.Instantiate.html" target="_blank" rel="noreferrer">UnityのInstantiate</a></p><p>有効な階層に作る場合、初期化用の処理が生成の途中で呼ばれることがあります。例えば<code>Awake</code>で参照を準備し、呼び出し元から値を渡す専用の初期化処理を別に設けるなど、どの時点で必要な値がそろうかを決めます。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Object.Instantiate.html" target="_blank" rel="noreferrer">Instantiateと初期化イベント</a></p><h2 id="生成後に呼ばれる処理を知る" tabindex="-1">生成後に呼ばれる処理を知る <a class="header-anchor" href="#生成後に呼ばれる処理を知る" aria-label="Permalink to &quot;生成後に呼ばれる処理を知る&quot;">​</a></h2><p>UnityのMonoBehaviourには、実行の段階に応じたイベント関数があります。次は代表的な役割です。実際に呼ばれる条件は、GameObjectやコンポーネントの有効状態などによって変わります。</p><table tabindex="0"><thead><tr><th>関数</th><th>基本の役割</th></tr></thead><tbody><tr><td><strong>Awake</strong></td><td>インスタンスの初期化時に、参照などを準備する。</td></tr><tr><td><strong>OnEnable</strong></td><td>コンポーネントが有効になり、階層内でも有効なときの処理。</td></tr><tr><td><strong>Start</strong></td><td>有効なスクリプトで、最初の更新の前に一度行う処理。</td></tr><tr><td><strong>Update</strong></td><td>有効な状態で、フレームごとの処理を進める。</td></tr><tr><td><strong>OnDisable</strong></td><td>無効になったときの処理。</td></tr></tbody></table><p><code>Start</code>は有効化のたびに繰り返される初期化としては使えません。無効から再び有効にするときにも必要な処理は、再有効化の入口へ置きます。初期化と他の物への参照に依存がある場合は、呼び出し順も確認します。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/MonoBehaviour.Awake.html" target="_blank" rel="noreferrer">UnityのAwake</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/MonoBehaviour.Start.html" target="_blank" rel="noreferrer">Start</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/GameObject.SetActive.html" target="_blank" rel="noreferrer">有効状態とSetActive</a></p><h2 id="無効にすることと、破棄すること" tabindex="-1">無効にすることと、破棄すること <a class="header-anchor" href="#無効にすることと、破棄すること" aria-label="Permalink to &quot;無効にすることと、破棄すること&quot;">​</a></h2><p><code>SetActive(false)</code>はGameObjectを無効にします。表示や更新など、その有効状態に従う処理が止まっても、インスタンス自体や保持している値は残ります。再び有効にすれば再利用できます。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/GameObject.SetActive.html" target="_blank" rel="noreferrer">UnityのSetActive</a></p><p><code>Destroy</code>はインスタンスの破棄を依頼します。Unityでは通常、実際の破棄は現在のUpdateループの後、描画の前へ遅延されます。GameObjectの破棄では、そのコンポーネントと子も対象になります。終了時の処理には<code>OnDestroy</code>などの入口があります。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Object.Destroy.html" target="_blank" rel="noreferrer">UnityのDestroy</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/MonoBehaviour.OnDestroy.html" target="_blank" rel="noreferrer">OnDestroy</a></p><p>弾を使い回す<strong>オブジェクトプール</strong>では、弾を無効にして待機させ、次の発射で再び使う構成があります。その場合は位置、速度、残り時間、HPなどを再利用用に初期化し、前の状態を持ち越す項目を決めます。参照や通知の登録も、利用する期間に合わせて扱います。<a href="/study/game/patterns/object-pool.html">Object Poolの詳解</a> · <a href="/study/game/basics/game-events-and-notifications.html">ゲーム内イベントと通知</a></p><h2 id="素材の寿命も追う" tabindex="-1">素材の寿命も追う <a class="header-anchor" href="#素材の寿命も追う" aria-label="Permalink to &quot;素材の寿命も追う&quot;">​</a></h2><p>同じ素材を複数の物から使う構成では、敵Aの利用が終わっても、敵Bが使い続けることがあります。素材の読み込みと解放を管理する際は、参照している利用者も追います。<a href="/study/game/asset-loading.html">アセットロードと所有権</a></p><p>更新のタイミングは<a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a>へ進みます。</p>',21)])])}const p=e(s,[["render",i]]);export{b as __pageData,p as default};
